import { AgentToolCall } from "@/components/design-for-ai/agent-tool-call";

<AgentToolCall
  seq={3}
  tool="web.search"
  args={{ query: "stripe proration rules", limit: 5 }}
  status={run.status}
  durationMs={run.durationMs}
  result={run.output}
  stderr={run.stderr}
  onRetry={() => agent.retry(run.id)} // the host also updates run.status
/>

